import { test, expect } from '@playwright/test';

test.describe('File Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/upload'); // Replace with the actual URL
  });

  test('should disable upload button while file is uploading', async ({ page }) => {
    const uploadInput = page.getByLabel('Upload File'); // Adjust the label as necessary
    const uploadButton = page.getByRole('button', { name: 'Upload' }); // Adjust the button name as necessary

    await uploadInput.setInputFiles('path/to/file.txt'); // Replace with the actual file path
    await expect(uploadButton).toBeDisabled();
  });

  test('should enable upload button after file upload is complete', async ({ page }) => {
    const uploadInput = page.getByLabel('Upload File'); // Adjust the label as necessary
    const uploadButton = page.getByRole('button', { name: 'Upload' }); // Adjust the button name as necessary

    await uploadInput.setInputFiles('path/to/file.txt'); // Replace with the actual file path
    await page.click(uploadButton);

    // Simulate waiting for the upload to complete
    await page.waitForTimeout(3000); // Adjust timeout as necessary

    await expect(uploadButton).toBeEnabled();
  });
});
